import 'package:flutter/material.dart'; import '../services/safety_service.dart';
class SafetyScreen extends StatefulWidget{const SafetyScreen({super.key});@override State<SafetyScreen> createState()=>_S();} class _S extends State<SafetyScreen>{final s=SafetyService();final reason=TextEditingController();final details=TextEditingController();Future<void>submit()async{if(reason.text.trim().isEmpty)return;await s.report(reason:reason.text,details:details.text);if(mounted){reason.clear();details.clear();ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Report submitted')));}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Safety & Trust')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Report a safety issue',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),TextField(controller:reason,decoration:const InputDecoration(labelText:'Reason')),TextField(controller:details,maxLines:4,decoration:const InputDecoration(labelText:'Details')),const SizedBox(height:12),FilledButton(onPressed:submit,child:const Text('Submit report')),const Divider(),ListTile(leading:const Icon(Icons.verified_user),title:const Text('Identity verification'),subtitle:const Text('Submit a verification request'),onTap:()=>Navigator.pushNamed(c,'/verification'))]));}
